SELECT d.id,d.project_id AS "projectId",question, jsonb_build_array('Resume dispatch','Keep paused') AS options, d.version, d.subject_version AS "subjectVersion", d.answer, d.request_id AS "requestId", CASE WHEN answer IS NOT NULL THEN 'answered' WHEN expires_at<=now() OR p.version<>subject_version THEN 'stale' ELSE 'pending' END AS status, expires_at AS "expiresAt" FROM decisions d JOIN projects p ON p.id=d.project_id WHERE d.workspace_id=$1 ORDER BY d.created_at DESC,d.id LIMIT 200
